// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Use two different proposers
        address proposer1 = address(0x123);
        address proposer2 = address(0x456);

        // Grant PROPOSER_ROLE to proposer1 and proposer2
        bytes32 proposerRole = keccak256("PROPOSER_ROLE");
        c.grantRole(proposerRole, proposer1);
        c.grantRole(proposerRole, proposer2);

        // proposer1 schedules a dummy operation
        bytes32 salt = keccak256("test");
        vm.prank(proposer1);
        c.schedule(address(0x789), 0, "", bytes32(0), salt, 1 days);

        // Warp past the delay so operation is ready, but not executed yet
        vm.warp(block.timestamp + 2 days);

        // Now proposer2 calls cancel; in the reference, hasRole(PROPOSER_ROLE, proposer2) is true -> cancel succeeds because operation is pending
        // In the buggy version, hasRole returns inverted value, so proposer2 is NOT considered a proposer -> cancel will revert
        vm.prank(proposer2);
        bytes32 id = c.hashOperation(address(0x789), 0, "", bytes32(0), salt);
        bool ok;
        try c.cancel(id) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: cancel succeeds (ok = true)
        // Buggy: cancel reverts (ok = false)
        assertTrue(ok);
    }
}

