pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Deploy with no proposers in arrays (only deployer has TIMELOCK_ADMIN_ROLE via _msgSender())
        // The constructor sets TIMELOCK_ADMIN_ROLE for msg.sender (this) and address(this) (the contract)
        // No PROPOSER_ROLE granted to any address initially
        address attacker = address(0x1234);

        // Grant PROPOSER_ROLE to attacker
        c.grantRole(c.PROPOSER_ROLE(), attacker);

        // Schedule an operation as attacker
        vm.prank(attacker);
        c.schedule(address(0), 0, "", bytes32(0), bytes32(0), 1 days);

        // Now try to cancel as a different address without PROPOSER_ROLE
        address nonProposer = address(0x5678);
        bytes32 operationId = c.hashOperation(address(0), 0, "", bytes32(0), bytes32(0));

        vm.prank(nonProposer);
        // In reference: hasRole(PROPOSER_ROLE, nonProposer) returns false -> modifier reverts
        // In bug: hasRole returns true (negated) -> modifier passes, then cancel checks isOperationPending which is true -> cancel succeeds unexpectedly
        bool success;
        try c.cancel(operationId) {
            success = true;
        } catch {
            success = false;
        }
        // Reference: cancel reverts (success = false)
        // Bug: cancel succeeds (success = true)
        assertTrue(success, "Cancel should succeed in bug but fails in reference");
        // NOTE: The above assertion expects success = true (bug behavior). 
        // In a proper test, we would assert the opposite, but the requirement says assertion must pass on reference and break on bug.
        // Since reference reverts (success=false) and bug succeeds (success=true), we assert success = true to fail reference and pass bug.
        // Re-reading requirement: "assertion the reference satisfies AND the bug breaks" means reference=true, bug=false.
        // Therefore we should assert success = false.
        // Let me correct:
        // Actually the reference cancel reverts -> success=false, bug cancel does not revert -> success=true
        // So to have reference satisfy (true) and bug break (false), we assert success == false.
        // But wait: reference does not succeed, so assertTrue(success) would fail on reference and pass on bug. That's opposite.
        // Let me re-evaluate: Requirement says "assertion the reference satisfies AND the bug breaks" — meaning reference passes the assert, bug fails it.
        // So we want an assert that is true for reference, false for bug.
        // In reference: cancel reverts -> success = false. assertTrue(success) = false. Not good.
        // Alternative: assertTrue(!success) -> works: !false = true for reference, !true = false for bug.
        // So assert true if cancel reverts.
        // Revising:
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Setup: propose a cancel operation
        bytes32 operationId = keccak256(abi.encode(address(1), 0, hex"12", bytes32(0), bytes32(0x1234)));
        // Prank as proposer (address(this) is proposer and executor)
        vm.prank(address(this));
        c.schedule(address(1), 0, hex"12", bytes32(0), bytes32(0x1234), 0);
        // Fast-forward to make operation ready
        vm.warp(block.timestamp + 1);
        // Now, an attacker (address(0xdead)) tries to renounce the proposer role for the original proposer
        // In the reference, this reverts because msg.sender != account.
        // In the buggy version, it succeeds and removes the proposer role.
        // Then we try to cancel: in reference, cancel works (role still there), in buggy it reverts.

        bool attackerCanRenounce = false;
        try c.renounceRole(keccak256("PROPOSER_ROLE"), address(this)) {
            attackerCanRenounce = true;
        } catch {
            attackerCanRenounce = false;
        }

        // Now attempt cancel
        bool cancelSuccess = false;
        vm.prank(address(this));
        try c.cancel(operationId) {
            cancelSuccess = true;
        } catch {
            cancelSuccess = false;
        }

        // Reference: attacker cannot renounce, cancel succeeds (true). Bug: attacker can renounce, cancel reverts (false).
        assertTrue(cancelSuccess == true);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Setup: get a proposer role (we are proposer already via constructor)
        bytes32 PROPOSER_ROLE = c.PROPOSER_ROLE();
        address proposer = address(this);
        address attacker = address(0x100);

        // Schedule an operation so it can be cancelled
        bytes32 id = c.hashOperation(address(0x200), 0, hex"", bytes32(0), bytes32(0x1234));
        c.schedule(address(0x200), 0, hex"", bytes32(0), bytes32(0x1234), 0);

        // Cancel the operation (as proposer)
        vm.prank(proposer);
        c.cancel(id);

        // Now attacker tries to renounce proposer role for the proposer
        vm.prank(attacker);
        c.renounceRole(PROPOSER_ROLE, proposer);

        // Assert: in reference, renounceRole reverts (caller != account) so proposer still has role
        // In bug, renounceRole succeeds, so proposer loses role
        bool stillHasRole = c.hasRole(PROPOSER_ROLE, proposer);
        assertTrue(stillHasRole, "Proposer should still have role (reference behavior)");
    }
}

