// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Schedule an operation as proposer
        bytes32 salt = bytes32(uint256(1));
        c.schedule(address(0x200), 0, hex"", bytes32(0), salt, 0);
        bytes32 opId = c.hashOperation(address(0x200), 0, hex"", bytes32(0), salt);
        // Fast-forward past delay
        vm.warp(block.timestamp + 1);
        // Attacker tries to renounce the proposer role for the proposer (address(this))
        bytes32 proposerRole = c.PROPOSER_ROLE();
        // In the reference contract, renounceRole reverts because account != msg.sender
        // In the buggy version, it succeeds
        // Use try/catch to detect revert
        bool attackerRenounceFailed = false;
        vm.prank(address(0x999));
        try c.renounceRole(proposerRole, address(this)) {
            attackerRenounceFailed = false;
        } catch {
            attackerRenounceFailed = true;
        }
        // The proposer should still have the role in the reference (so cancel works)
        // But in the buggy version, the role is renounced, so cancel fails with missing role
        bool cancelSucceeded = false;
        vm.prank(address(this));
        try c.cancel(opId) {
            cancelSucceeded = true;
        } catch {
            cancelSucceeded = false;
        }
        // Assert: in reference, attacker renounceRole reverts (so attackerRenounceFailed true)
        // and cancel succeeds (cancelSucceeded true)
        // In buggy version, attacker renounceRole succeeds, cancel fails
        // So we assert both conditions
        assertTrue(attackerRenounceFailed == true && cancelSucceeded == true);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Schedule an operation with delay 0 (minDelay is 0 from constructor)
        // Use a proposer (this contract is the sender and has PROPOSER_ROLE)
        // Target: this contract itself, value: 0, data: empty, predecessor: 0, salt: 0, delay: 0
        bytes32 id = c.hashOperation(address(this), 0, "", bytes32(0), bytes32(0));
        c.schedule(address(this), 0, "", bytes32(0), bytes32(0), 0);
        // Warp to make the operation ready (timestamp scheduled = block.timestamp + 0)
        vm.warp(block.timestamp);
        // Execute as a random non-admin account (e.g., address(0xdead))
        // Note: address(0) has EXECUTOR_ROLE because NOT granted, but onlyRoleOrOpenRole allows if address(0) has the role
        // However address(0) is not address(this) and does NOT have TIMELOCK_ADMIN_ROLE
        vm.prank(address(0xdead));
        // The correct contract should revert because _afterCall requires TIMELOCK_ADMIN_ROLE and msg.sender is not admin
        // The buggy contract (with renounceRole changed) does not affect this flow — so both revert?
        // Wait: the property says P and M differ AFTER cancel(...). But cancel requires PROPOSER_ROLE.
        // Let's reconsider: We need a scenario where the change to renounceRole causes a difference via cancel.
        // The change is: renounceRole now requires account != _msgSender(), so self-renounce is blocked.
        // In P, a proposer can renounce their own role. In M, they cannot.
        // After cancel(...), the state of renounceRole function itself is unchanged; but the difference is that in M,
        // a call to renounceRole by self reverts, whereas in P it succeeds.
        // So we test: after cancel (which doesn't call renounceRole), we call renounceRole on self and observe revert.
        // Setup: give a proposer role to address(this), then call cancel (no effect), then call renounceRole on self.
        // Clearer: directly test the difference: call renounceRole on self and check if it reverts.
        // Let's do that.
        c.cancel(bytes32(0)); // cancels nothing, just a call
        // Now renounce self's role:
        bool ok;
        try c.renounceRole(bytes32(0), address(this)) { ok = true; } catch { ok = false; }
        // In reference P, it succeeds (true). In buggy M, it reverts (false).
        assertTrue(ok); // reference: true; buggy: false
    }
}

