pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Set up: grant EXECUTOR_ROLE to address(0) to make it an open role
        c.grantRole(c.EXECUTOR_ROLE(), address(0));
        // Schedule an operation with delay 0 (minDelay = 0 from constructor)
        address target = address(0x1234);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(0x5678);
        uint256 delay = 0;
        c.schedule(target, value, data, predecessor, salt, delay);
        // Warp to make the operation ready (timestamp >= block.timestamp)
        vm.warp(block.timestamp + 1);
        // Attempt to execute as a non-admin account (e.g., address(this) is admin, so we prank as a different address)
        address executor = address(0xdead);
        vm.deal(executor, 1 ether);
        vm.prank(executor);
        bool ok;
        try c.execute{value: 0}(target, value, data, predecessor, salt) {
            ok = true;
        } catch {
            ok = false;
        }
        // The correct contract (with open executor role) allows execution;
        // the buggy contract (with renounceRole change) reverts in _afterCall because executor lacks TIMELOCK_ADMIN_ROLE.
        assertTrue(ok);
    }
}

