import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    function testRegression_property() public {
        // Schedule an operation with delay 0 (immediately executable)
        bytes32 salt = keccak256("test");
        address target = address(0xdead);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        uint256 delay = 0;
        c.schedule(target, value, data, predecessor, salt, delay);

        // Warp ahead so operation is ready
        vm.warp(block.timestamp + 1);

        // Execute the operation to mark it DONE
        c.execute(target, value, data, predecessor, salt);

        // Now the operation has timestamp == 1 (DONE). In reference, isOperation returns true
        // so cancel will revert because isOperationPending returns false (timestamp not > 1).
        // In mutant, isOperation always returns false, so cancel proceeds but requires isOperationPending
        // (which checks getTimestamp > 1). Both should be false, but let's check the cancel revert.

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        bool cancelSucceeded;
        try c.cancel(id) {
            cancelSucceeded = true;
        } catch {
            cancelSucceeded = false;
        }

        // Reference: cancel reverts because isOperationPending(id) fails (timestamp = 1, not > 1)
        // Mutant: cancel reverts because isOperationPending(id) also fails (timestamp = 1)
        // But the divergence we need: isOperation returns true in reference (timestamp > 0)
        // and false in mutant. So let's check isOperation directly:

        bool refIsOperation = c.getTimestamp(id) > 0; // true for reference

        // For the mutant, isOperation returns false always
        // This assert checks that the reference's isOperation would be true
        assertTrue(refIsOperation);
    }
}

