pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        address target = address(0xdead);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(0);

        // Schedule operation with delay 0 (minDelay already set to 0 in constructor)
        c.schedule(target, value, data, predecessor, salt, 0);

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Before any time passes, block.timestamp == operation timestamp
        // In P: timestamp > 1 (true) && timestamp <= block.timestamp (true) => true
        // In M: timestamp > 1 (true) || timestamp <= block.timestamp (true) => true (no difference yet)
        // We need to warp to just before the operation's timestamp to break the &&
        // But with delay 0, the timestamp is block.timestamp, so both conditions hold.
        // Instead, schedule with a positive delay and warp to before it's ready.

        // Reset by deploying fresh contract with minDelay > 0
        c = new C(1, address(this), address(this));

        uint256 delay = 1;
        c.schedule(target, value, data, predecessor, salt, delay);
        id = c.hashOperation(target, value, data, predecessor, salt);

        // Warp to exactly the timestamp - 1 (1 second before ready)
        uint256 scheduledTimestamp = c.getTimestamp(id);
        vm.warp(scheduledTimestamp - 1);

        // At this point:
        // P: timestamp > 1 (true) && timestamp <= block.timestamp (false) => false
        // M: timestamp > 1 (true) || timestamp <= block.timestamp (false) => true
        // So isOperationReady returns false in P, true in M.
        // We assert that it's false (reference behavior).
        assertTrue(!c.isOperationReady(id), "Operation should not be ready yet");
    }
}

