pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Set block.timestamp to a known value
        vm.warp(1000);

        // Schedule an operation with delay = 100, so it becomes ready at block.timestamp = 1100
        bytes32 salt = keccak256("test");
        address target = address(0xdead);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        uint256 delay = 100;
        c.schedule(target, value, data, predecessor, salt, delay);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Warp to exactly block.timestamp = 1100 (the operation is ready)
        vm.warp(1100);

        // Now warp to block.timestamp = 1101 and check isOperationReady
        vm.warp(1101);

        // For the reference contract, isOperationReady(id) should be true (timestamp 1100 <= 1101)
        // For the buggy contract with strict <, isOperationReady(id) would be false (1100 < 1101 is true, but first condition timestamp >= _DONE_TIMESTAMP is also true, so it returns true)
        // Actually the bug changes <= to <, so the condition becomes timestamp >= _DONE_TIMESTAMP && timestamp < block.timestamp.
        // At block.timestamp = 1101, timestamp = 1100, so 1100 >= 1 (true) and 1100 < 1101 (true) => returns true for both.
        // We need a case where the reference returns true and the bug returns false, or vice versa.
        // The difference: reference uses timestamp <= block.timestamp, bug uses timestamp < block.timestamp.
        // So at the exact moment block.timestamp == timestamp, reference returns true, bug returns false.
        // Let's do: schedule with delay = 100 at time = 1000, so ready at 1100.
        // Warp to 1100 exactly. Reference isOperationReady returns true, bug returns false.
        // Then cancel should succeed on reference (since operation is pending and ready? Actually cancel only requires isOperationPending, not isOperationReady. So cancel will succeed on both.)
        // We need a difference in cancel behavior: cancel requires isOperationPending(id) which is timestamp > _DONE_TIMESTAMP (1). So at timestamp = 1100, it's pending.
        // cancel does not call isOperationReady. So the divergence in isOperationReady alone won't affect cancel.
        // But the prompt says: "Driven through the public/external entry cancel(bytes32), P and M differ in this way: a call isOperationReady(args) that completes (does not revert) in both P and M, but returns different values."
        // So we need to show that after some sequence, isOperationReady returns different values. That's the assertion.
        // Let's use the exact boundary: timestamp == block.timestamp.
        vm.warp(1100);
        bool refReady = c.isOperationReady(id); // should be true
        // Now warp to 1099 so the reference returns false? No, the bug returns false when timestamp < block.timestamp? Actually both return true when timestamp < block.timestamp.
        // The difference: when timestamp == block.timestamp, reference: timestamp <= block.timestamp => true; bug: timestamp < block.timestamp => false.
        // So we can assert that at block.timestamp == timestamp, reference returns true.
        // But we need the test to pass on reference and fail on bug. Since this is a Foundry test running against the deployed contract, we need to check the actual behavior.
        // We'll assert that isOperationReady returns true. On the reference it does, on the bug it returns false => test fails on bug.
        assertTrue(c.isOperationReady(id), "isOperationReady should be true when timestamp == block.timestamp");
    }
}

